"""Offline Korean research viewer: policy changes, held-out matches, game replay."""
import json
from pathlib import Path

from baseball_lab.labels import LABELS, korean


def write_report(output: Path, payload: dict, replay: dict):
    data = json.dumps({'training': payload, 'replay': replay, 'labels': LABELS}, ensure_ascii=False).replace('<', '\\u003c')
    html = r'''<!doctype html>
<html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>야구 AI 연구실 · 전략의 변화</title>
<style>
:root{color-scheme:dark;--bg:#101a18;--panel:#1a2925;--muted:#aec3b8;--green:#a1efab;--line:#385047}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#f1f5eb;font:16px/1.65 system-ui,'Malgun Gothic',sans-serif}main{max-width:1160px;margin:auto;padding:40px 24px 80px}h1{font-size:clamp(28px,5vw,48px);line-height:1.3;margin:12px 0}h2{font-size:24px}h3{font-size:17px}small,.muted{color:var(--muted)}header{border-bottom:1px solid var(--line);padding-bottom:28px}section{margin-top:28px;padding:24px;background:var(--panel);border:1px solid var(--line);border-radius:14px}.tag{display:inline-block;border:1px solid var(--green);border-radius:20px;padding:3px 12px;margin:3px;color:var(--green);font-size:13px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:22px}select{background:var(--bg);color:inherit;padding:10px;border:1px solid var(--line);border-radius:6px;max-width:100%}input[type=range]{width:100%;accent-color:var(--green)}.bar{height:12px;background:#344a40;border-radius:8px;overflow:hidden}.fill{height:100%;background:var(--green)}.row{margin:14px 0}.rowlabel{display:flex;justify-content:space-between;font-size:14px}.big{font-size:32px;font-weight:700;color:var(--green)}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;border-bottom:1px solid var(--line);padding:10px}svg{width:100%;max-height:240px}.tablewrap{overflow:auto}.score{font-size:32px;letter-spacing:3px}.note{border-left:3px solid var(--green);padding-left:14px}button{background:var(--green);color:#102019;border:0;border-radius:5px;padding:10px 16px;cursor:pointer}a{color:var(--green)}
</style><main>
<header><span class="tag">야구 AI 연구실</span><span class="tag" id="experimentTitle">타자·투수 경쟁 학습</span><span class="tag">합성 야구 환경</span>
<h1>이기려는 AI는<br>어떤 야구를 선택할까?</h1><p class="muted">타격·투구 전략을 정답으로 지정하지 않고, 경기 승패만으로 두 신경망 정책을 학습시킨 기록입니다.</p><div class="grid"><div>완료한 학습 경기<div id="games" class="big"></div></div><div>경기 규칙<div id="innings" class="big"></div></div><div>학습 보상<div class="big">승 +1 · 패 −1 · 무 0</div></div></div></header>
<section><h2>1. 같은 상대에게 더 잘 대응하는가?</h2><p class="muted">평가 중에는 가중치를 바꾸지 않습니다. 매 세대 같은 평가 시드를 사용하고 선후공을 교환합니다. 자기대결 성적과 구분해 보세요.</p><label>평가 상대 <select id="opponent"></select></label><svg viewBox="0 0 900 200" id="chart" role="img" aria-label="학습 경기 수에 따른 고정 상대 승률"></svg><div class="tablewrap"><table><thead><tr><th>상대</th><th id="beforeHeader">학습 전</th><th>현재</th><th>현재 승·패·무</th><th>경기당 득점 / 실점</th></tr></thead><tbody id="evaluation"></tbody></table></div><p class="muted">승률 변화 한 번만으로 학습 성공이나 실제 야구의 우열을 결론낼 수 없습니다. 다른 학습 seed와 보정 모델에서도 재검증해야 합니다.</p></section>
<section><h2>2. 같은 상황에서 선택이 어떻게 바뀌었나?</h2><p class="muted">서로 다른 경기 장면을 섞어 비교하지 않도록, 각 세대에 똑같은 공개 상황을 입력한 행동 확률입니다.</p><label>학습 시점 <strong id="generationLabel"></strong><input id="generation" type="range" min="0" step="1"></label><label>상황 <select id="situation"></select></label><div class="grid"><div><h3>타자의 선택</h3><div id="batBars"></div></div><div><h3>투수의 존 공략</h3><div id="zoneBars"></div><h3>투구 강도</h3><div id="effortBars"></div></div><div><h3>투수의 구종</h3><div id="pitchBars"></div></div></div><p class="note">번트·강공·인내·유인구를 선택하도록 보상하지 않았습니다. 이 확률은 학습된 선택이며, 전략이 생긴 원인에 대한 설명은 별도의 검증이 필요합니다.</p></section>
<section><h2>3. 학습된 팀의 경기 따라보기</h2><p class="muted">학습 팀이 원정으로 나선 고정 상대 평가 경기입니다. 아래 슬라이더로 모든 투구와 주자·점수 변화를 살펴보세요.</p><div id="score" class="score"></div><div id="scene"></div><svg viewBox="0 0 400 230" style="max-height:200px" role="img" aria-label="플레이 후 주자 위치"><path d="M200 210 L360 110 L200 10 L40 110 Z" fill="#344a40" stroke="#aec3b8"/><path d="M200 210 L280 130 L200 50 L120 130 Z" fill="#835f3e" stroke="#f1f5eb"/><circle id="base1" cx="280" cy="130" r="13" stroke="#f1f5eb"/><circle id="base2" cx="200" cy="50" r="13" stroke="#f1f5eb"/><circle id="base3" cx="120" cy="130" r="13" stroke="#f1f5eb"/><text x="295" y="135" fill="#f1f5eb">1루</text><text x="220" y="50" fill="#f1f5eb">2루</text><text x="73" y="135" fill="#f1f5eb">3루</text><text x="145" y="229" fill="#aec3b8">플레이 후 주자</text></svg><input id="replay" type="range" min="0" step="1"><button id="play">자동 재생</button><p id="actions"></p><p id="event" class="note"></p></section>
<section><h2>연구 조건과 해석</h2><p>확률 결과·능력·피로·번트와 주자 진루는 합성 모델입니다. 각 팀은 같은 선수 능력으로 경기합니다. 현재는 동질 선수, 보수적인 진루, 간이 병살, 번트, 단일 투수의 피로를 사용하며 수비·주루·교체 결정은 자동 처리합니다. 실제 MLB/KBO 데이터로 보정한 모델이 아닙니다.</p><p>알고리즘은 두 은닉층 신경망의 정책경사 강화학습(REINFORCE)입니다. 관측은 카운트·이닝·점수·주자·아웃·공개된 투구 부하이며, 타자는 현재 투구의 구종·코스를 미리 보지 못합니다. 3종 구종 × 존/유인구 × 3단계 강도, 타자의 4개 행동을 선택합니다.</p><p class="muted">학습 곡선·평가·행동 확률: training.json · 학습 모델: checkpoints/ · 재생: replay.json · 요약: summary.md</p></section></main>
<script>const D=__DATA__;const T=D.training,H=T.history,$=id=>document.getElementById(id),label=x=>D.labels[x]||x,pct=x=>(100*x).toFixed(1)+'%';
$('experimentTitle').textContent=label(T.experiment_id);if(T.evaluation_only){$('chart').style.display='none';document.querySelector('h1').textContent='저장된 AI의 경기 다시보기';$('beforeHeader').textContent='학습 전 자료';}$('games').textContent=H[H.length-1].games.toLocaleString()+'경기';$('innings').textContent=T.config.innings+'이닝 · 최대 '+T.game_rules.max_extra_innings+'이닝 연장';
function option(select,text,value){let o=document.createElement('option');o.textContent=text;o.value=value;select.append(o)}H[0].evaluation.forEach((e,i)=>option($('opponent'),label(e.opponent),i));H[0].probes.forEach((p,i)=>option($('situation'),p.situation,i));$('generation').max=H.length-1;$('generation').value=H.length-1;
function bars(id,values){let root=$(id);root.replaceChildren();Object.entries(values).forEach(([name,value])=>{let row=document.createElement('div');row.className='row';let text=document.createElement('div');text.className='rowlabel';let n=document.createElement('span'),v=document.createElement('span');n.textContent=name;v.textContent=pct(value);text.append(n,v);let bar=document.createElement('div');bar.className='bar';let fill=document.createElement('div');fill.className='fill';fill.style.width=pct(value);bar.append(fill);row.append(text,bar);root.append(row)})}
function draw(){let k=+$('generation').value,s=+$('situation').value,e=H[k],p=e.probes[s];$('generationLabel').textContent=e.games.toLocaleString()+'경기';bars('batBars',p.batter);bars('zoneBars',p.zone);bars('effortBars',p.effort);bars('pitchBars',p.pitch_type);$('evaluation').replaceChildren();e.evaluation.forEach((v,i)=>{let row=document.createElement('tr');[label(v.opponent),T.evaluation_only?'미포함':pct(H[0].evaluation[i].win_rate),pct(v.win_rate),`${v.wins}승 ${v.losses}패 ${v.draws}무`,`${v.runs_for.toFixed(2)} / ${v.runs_against.toFixed(2)}`].forEach(x=>{let c=document.createElement('td');c.textContent=x;row.append(c)});$('evaluation').append(row)});let svg=$('chart');svg.replaceChildren();const ns='http://www.w3.org/2000/svg',opp=+$('opponent').value;for(let y=0;y<=1;y+=.25){let line=document.createElementNS(ns,'line');line.setAttribute('x1',50);line.setAttribute('x2',860);line.setAttribute('y1',170-140*y);line.setAttribute('y2',170-140*y);line.setAttribute('stroke','#385047');svg.append(line);let text=document.createElementNS(ns,'text');text.setAttribute('x',0);text.setAttribute('y',175-140*y);text.setAttribute('fill','#aec3b8');text.textContent=Math.round(y*100)+'%';svg.append(text)}let poly=document.createElementNS(ns,'polyline');poly.setAttribute('points',H.map(h=>`${50+810*h.games/Math.max(T.config.games,1)},${170-140*h.evaluation[opp].win_rate}`).join(' '));poly.setAttribute('fill','none');poly.setAttribute('stroke','#a1efab');poly.setAttribute('stroke-width',3);svg.append(poly);[0,T.config.games].forEach((n,i)=>{let t=document.createElementNS(ns,'text');t.setAttribute('x',i?790:50);t.setAttribute('y',197);t.setAttribute('fill','#aec3b8');t.textContent=n+'경기';svg.append(t)})}
$('generation').oninput=draw;$('situation').onchange=draw;$('opponent').onchange=draw;draw();
const R=D.replay.events||[];$('replay').max=Math.max(0,R.length-1);function replay(){let i=+$('replay').value,r=R[i];if(!r){$('scene').textContent='재생 기록이 없습니다.';return}$('score').textContent=`학습 팀 ${r.away_score} : ${r.home_score} 적극 공격·혼합 투구 팀`;$('scene').textContent=`${r.inning}회 ${r.bottom?'말':'초'} · 투구 전 ${r.outs_before}아웃 · ${r.balls}볼 ${r.strikes}스트라이크 · 주자 ${r.bases_before.map((v,i)=>v?(i+1)+'루':'').filter(Boolean).join('·')||'없음'}`;$('actions').textContent=`${i+1}/${R.length}구 | 타자: ${label(r.batter_action)} | 투수: ${label(r.pitch_type)} · ${r.target_zone?'존 공략':'유인구 목표'} · ${r.effort===1?'전력':r.effort===-1?'절약':'보통'} 투구`;r.bases_after.forEach((v,j)=>$('base'+(j+1)).setAttribute('fill',v?'#a1efab':'#101a18'));$('event').textContent=`결과: ${label(r.event)}${r.result?' → '+label(r.result):''} · ${r.runs}득점 · 투구 후 ${r.outs_after}아웃`}let timer=null;$('replay').oninput=replay;$('play').onclick=()=>{if(timer){clearInterval(timer);timer=null;$('play').textContent='자동 재생';return}$('play').textContent='정지';timer=setInterval(()=>{let next=+$('replay').value+1;if(next>=R.length){clearInterval(timer);timer=null;$('play').textContent='자동 재생';return}$('replay').value=next;replay()},350)};replay();</script></html>'''
    (output/'report.html').write_text(html.replace('__DATA__', data), encoding='utf-8')
    first, last = payload['history'][0], payload['history'][-1]
    lines = ['# 타자·투수 경쟁 학습 결과', '',
             f"학습 {payload['config']['games']}경기, {payload['config']['innings']}이닝 규칙, seed {payload['config']['seed']}.",
             '저장 정책을 가중치 갱신 없이 재평가한 결과다.' if payload.get('evaluation_only') else '보상은 경기 종료의 승리 +1 / 패배 -1 / 무승부 0뿐이다. 학습 상대는 고정 기준선과 과거 신경망 팀이다.', '',
             '| 고정 평가 상대 | 학습 전 승률 | 학습 후 승률 | 후 승/패/무 |', '|---|---:|---:|---|']
    for before, after in zip(first['evaluation'], last['evaluation']):
        lines.append(f"| {korean(after['opponent'])} | {format(before['win_rate'], '.1%') if not payload.get('evaluation_only') else '미포함'} | {after['win_rate']:.1%} | {after['wins']}/{after['losses']}/{after['draws']} |")
    lines.extend(['', '## 같은 상황의 행동 변화', ''])
    for before, after in zip(first['probes'], last['probes']):
        lines.append(f"### {before['situation']}")
        for group in ('batter', 'zone', 'effort'):
            lines.extend(f"- {name}: {p:.1%} → {after[group][name]:.1%}" for name, p in before[group].items())
        lines.append('')
    lines.extend(['## 해석', '',
                  '학습 보고서는 정책경사로 가중치를 갱신한 결과이며, 재평가 보고서는 저장 정책을 고정해 실행한 결과다. 평가 상대·시드·선후공 조건을 기록한다. 행동 변화와 평가 성능을 함께 확인해야 하며 단일 학습 seed나 작은 평가 표본으로 우월한 전략을 확정하지 않는다.',
                  '합성 결과 모델, 동질 선수, 간이 주루·병살·피로·번트 가정이다. 확률 모델의 편향을 학습할 수 있으므로 실제 인간 야구와의 비교에는 데이터 보정과 다른 환경 검증이 필요하다.',
                  '최종 체크포인트는 재평가·재생할 수 있다. 중단 시점부터 상대 풀/RNG/학습 이력을 모두 복원하는 재시작은 아직 제공하지 않는다.', ''])
    (output/'summary.md').write_text('\n'.join(lines), encoding='utf-8')
